CREATE TABLE IF NOT EXISTS concept (concept_id TEXT PRIMARY KEY, cui TEXT UNIQUE, preferred_name TEXT NOT NULL, graph_version TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS term (term_id TEXT PRIMARY KEY, concept_id TEXT REFERENCES concept(concept_id), text TEXT NOT NULL, normalized_text TEXT NOT NULL, language TEXT DEFAULT 'ENG', source_system TEXT);
CREATE TABLE IF NOT EXISTS semantic_type (semantic_type_id TEXT PRIMARY KEY, name TEXT NOT NULL, entity_type TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS entity (entity_id TEXT PRIMARY KEY, entity_type TEXT NOT NULL, preferred_name TEXT NOT NULL, canonical_cui TEXT, identifiers JSONB DEFAULT '{}'::jsonb, semantic_types TEXT[] DEFAULT '{}', is_active BOOLEAN DEFAULT TRUE, graph_version TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS entity_identifier (entity_id TEXT REFERENCES entity(entity_id), namespace TEXT NOT NULL, identifier TEXT NOT NULL, PRIMARY KEY(entity_id, namespace, identifier));
CREATE TABLE IF NOT EXISTS entity_merge (source_entity_id TEXT NOT NULL, target_entity_id TEXT REFERENCES entity(entity_id), confidence DOUBLE PRECISION NOT NULL, reason TEXT, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS assertion (assertion_id TEXT PRIMARY KEY, subject_id TEXT REFERENCES entity(entity_id), predicate TEXT NOT NULL, object_id TEXT REFERENCES entity(entity_id), polarity TEXT DEFAULT 'positive', directionality TEXT DEFAULT 'directed', confidence DOUBLE PRECISION DEFAULT 0, source_system TEXT NOT NULL, source_record_id TEXT NOT NULL, source_predicate TEXT, source_release TEXT, graph_version TEXT NOT NULL, is_current BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS assertion_qualifier (assertion_id TEXT REFERENCES assertion(assertion_id), qualifier_key TEXT NOT NULL, qualifier_value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS evidence_span (evidence_id TEXT PRIMARY KEY, doc_id TEXT NOT NULL, chunk_id TEXT, text TEXT NOT NULL, section TEXT, offset_start INTEGER, offset_end INTEGER, evidence_type TEXT, publication_date DATE, source_system TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS source_record (source_record_id TEXT PRIMARY KEY, source_system TEXT NOT NULL, release_name TEXT, payload JSONB NOT NULL);
CREATE TABLE IF NOT EXISTS document (doc_id TEXT PRIMARY KEY, source TEXT NOT NULL, title TEXT, authors TEXT[] DEFAULT '{}', publication_date DATE, license TEXT, text_hash TEXT, is_current BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS document_section (section_id TEXT PRIMARY KEY, doc_id TEXT REFERENCES document(doc_id), section_title TEXT, text TEXT);
CREATE TABLE IF NOT EXISTS document_chunk (chunk_id TEXT PRIMARY KEY, doc_id TEXT REFERENCES document(doc_id), section_id TEXT, section TEXT, text TEXT NOT NULL, text_hash TEXT, entity_ids TEXT[] DEFAULT '{}', cuis TEXT[] DEFAULT '{}', semantic_types TEXT[] DEFAULT '{}', is_current BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS chunk_entity_mention (chunk_id TEXT REFERENCES document_chunk(chunk_id), entity_id TEXT REFERENCES entity(entity_id), mention_text TEXT NOT NULL, confidence DOUBLE PRECISION NOT NULL);
